package interpreter

import org.junit.jupiter.api.TestInstance
import java.nio.file.Paths
import java.time.Duration

/**
 * The unstable funcon corpus, as vendored under `CBS-beta/Unstable-Funcons-beta`.
 *
 * Only the corpora whose semantics the generator can currently produce are
 * walked. Each is generated by `:fctlang-unstable`, whose render list is the
 * acceptance gate kept in `fctlang-unstable/build.gradle.kts`; a corpus that
 * still relies on a gap in `trufflegen` is added here when its rule forms are
 * supported.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TestUnstableBeta : BaseTest(
    testDirectories = listOf(
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Normal/Memos/tests") to "config",
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Normal/Indexing/tests") to "config",
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Abnormal/Postponing/tests") to "config",
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Threads/Multithreading/tests") to "config",
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Threads/Synchronising/Locks/tests") to "config",
        Paths.get("../CBS-beta/Unstable-Funcons-beta/Computations/Threads/Synchronising/Notifications/tests") to "config"
    ),
    performTiming = false,
    perTestTimeout = Duration.ofSeconds(20)
)